---@class  RoleVoiceMgr
---@field GetInstance fun(self:RoleVoiceMgr):RoleVoiceMgr
local RoleVoiceMgr = Class("RoleVoiceMgr", Singleton)


function RoleVoiceMgr:__init()
    local now = CS.System.DateTime.UtcNow
    local dayStr = ChinaDate.GetDay(now)
    local monthStr = ChinaDate.GetMonth(now)
    self._chinaDate = monthStr..dayStr
    local dateObj = date(true)
    self._dateStr = dateObj:fmt('%m%d')
    self._birthDay = string.format('%d-%d', dateObj:getmonth(),dateObj:getday())
end

function RoleVoiceMgr:__delete()
    self._chinaDate = nil
    SettingModule.RemoveFileCacheByPath(voiceFestivalSettingPath)
    SettingModule.RemoveFileCacheByPath(voiceRolesSettingPath)
    SettingModule.RemoveFileCacheByPath(voiceCardsSettingPath)
    SettingModule.RemoveFileCacheByPath(voiceSettingPath)
end

function RoleVoiceMgr:GetTimeOfDay()
    local dateObj = date()
    ---得当当前《时》的值
    return dateObj:gethours()
end


