---获取图鉴中指定角色的语音信息
---@param roleId number
---@return RoleVoiceVo[]
function RoleVoiceMgr:GetVoicesByRoleId(roleId)
    local t = {}
    ---@type TableML.TableFile
    local tableFile = SettingModule.Get(voiceIllustratedRolesSettingPath)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(roleId, false)
    local settingMgr = SettingMgr:GetInstance()
    if row then
        local id_string = row:Get("ids")
        local ids = string.split(id_string, ',')
        local setting = settingMgr:GetSetting(voiceSettingPath, "RoleVoiceVo")
        for i, id in pairs(ids) do
            if checkNumber(setting:Get(id).showInBook) == 1 then--显示在图鉴中
                table.insert(t, setting:Get(id))
            end
        end
    end
    return t
end


