---播放卡牌的语音与类型
---@param cardId number
---@param type number
---@param go UnityEngine.GameObject
---@param canTimeStrentch2D boolean @ 使用2D播放器并且可以加速
---@param skinId? number
---@return RoleVoiceVo | nil
function RoleVoiceMgr:__PlayVoiceByCardIdAndType(cardId, type, go, canTimeStrentch2D, skinId)
    local skinIdStr = checkNumber(skinId) > 0 and skinId or ""
    local primaryKey = string.format('%s_%s_%s', cardId, skinIdStr, type)
    ---@type TableML.TableFile
    local tableFile = SettingModule.Get(voiceCardsSettingPath)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(primaryKey, false)
    ---尝试获取下 默认的row
    if skinId and row == nil then
        primaryKey = string.format('%s_%s_%s', cardId, "", type)
        row = tableFile:GetByPrimaryKey(primaryKey, false)
    end
    local settingMgr = SettingMgr:GetInstance()
    if row then
        local id_string = row:Get("ids")
        local ids = string.split(id_string, ',')
        local position = math.random(1, #ids)
        local id = ids[position]
        local setting = settingMgr:GetSetting(voiceSettingPath, "RoleVoiceVo")
        ---@type RoleVoiceVo
        local vo = setting:Get(id)
        CriWareUtils.PlayVoiceVoById(vo, go, canTimeStrentch2D)
        return vo
    end
end


---处理节日的语音播放的逻辑
---@param cardId number
---@param go UnityEngine.GameObject
---@return RoleVoiceVo[]
function RoleVoiceMgr:PlayFestivalVoiceByCardId(cardId, go)
    ---@type CardVo
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    if cardVo == nil then return end
    
    local roleId = cardVo.characterId
    ---@type TableML.TableFile
    local tableFile = SettingModule.Get(voiceFestivalSettingPath)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(roleId, false)
    local settingMgr = SettingMgr:GetInstance()
    ---@type RoleVoiceVo[]
    local t = {}
    if row then
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local birthday = playerComponent.playerDojo.birthday
        local id_string = row:Get("ids")
        local ids = string.split(id_string, ',')
        local setting = settingMgr:GetSetting(voiceSettingPath, "RoleVoiceVo")
        for i, id in pairs(ids) do
            ---@type RoleVoiceVo
            local vo = setting:Get(id)
            if vo.given == '1' and not string.isEmpty(birthday) then
                ---玩家生日
                if self._birthDay == birthday then
                    table.insert(t, vo)
                end
            else
                if vo.given == self._dateStr then
                    table.insert(t, vo)
                end
                if vo.given == self._chinaDate then
                    table.insert(t, vo)
                end
            end
        end
        if #t > 0 then
            SortByMember(t, 'priority')
            ---@type RoleVoiceVo
            local vo = t[1]
            CriWareUtils.PlayVoiceVoById(vo, go)
        end
    end
    return t
end


