---给播放初次进入游戏与主界面点击时的逻辑处理
---@param cardId number
---@param t_type number
---@param go UnityEngine.GameObject
---@param ignoreVoice boolean
---@param skinId? string
---@return RoleVoiceVo | nil
function RoleVoiceMgr:__PlayRoleVoiceByCardIdAndLevel(cardId, t_type, go, ignoreVoice, skinId)
    ignoreVoice = checkBool(ignoreVoice)
    local skinIdStr = checkNumber(skinId) > 0 and skinId or ""
    local primaryKey = string.format('%s_%s_%s', cardId, skinIdStr, t_type)
    ---@type TableML.TableFile
    local tableFile = SettingModule.Get(voiceCardsSettingPath)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(primaryKey, false)
    ---尝试获取下 默认的row
    if skinId and row == nil then
        primaryKey = string.format('%s_%s_%s', cardId, "", t_type)
        row = tableFile:GetByPrimaryKey(primaryKey, false)
    end
    local settingMgr = SettingMgr:GetInstance()
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardByConfId(cardId)
    local loveLevel = cardDojo and  checkInt(cardDojo.favorabilityLevel) or 6
    if row and loveLevel >= 0 then
        ---@type RoleVoiceVo[]
        local t = {}
        local id_string = row:Get("ids")
        local ids = string.split(id_string, ',')
        local setting = settingMgr:GetSetting(voiceSettingPath, "RoleVoiceVo")
        for i, id in pairs(ids) do
            ---@type RoleVoiceVo
            local vo = setting:Get(id)
            if not string.isEmpty(vo.targetNum) then
                if loveLevel >= checkInt(vo.targetNum) then
                    table.insert(t, vo)
                end
            end
        end
        if #t >0 then
            local position = math.random(1, #t)
            ---@type RoleVoiceVo
            local vo = t[position]
            if not ignoreVoice then
                CriWareUtils.PlayVoiceVoById(vo, go)
            end
            return vo
        end
    end
end


---@param vo RoleVoiceVo
---@return integer, boolean
function RoleVoiceMgr:IsValidTime(vo)
    local checkTime = checkInt(vo.time) > 0
    local isValid = false
    if checkInt(vo.time) > 0 and SpanTimes[tostring(vo.time)] then
        local timeOfDay = self:GetTimeOfDay()
        local t = SpanTimes[tostring(vo.time)]
        if timeOfDay >= t.min and timeOfDay < t.max then
            isValid = true
        end
    end
    return checkTime, isValid
end


---给播放初次进入游戏与主界面点击时的逻辑处理
---@param roleId number
---@param t_type number
---@param go UnityEngine.GameObject
---@return RoleVoiceVo | nil
function RoleVoiceMgr:__PlayRoleVoiceByRoleIdAndLevel(roleId, t_type, go)
    local roleId = checkNumber(roleId)
    if roleId == 0 then
        return nil
    end
    
    local primaryKey = string.format('%s_%s', roleId, t_type)
    ---@type TableML.TableFile
    local tableFile = SettingModule.Get(voiceRolesSettingPath)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(primaryKey, false)
    local settingMgr = SettingMgr:GetInstance()
    local loveLevel,_ = PhoneUtils.GetCatFavorabilityLevel(roleId)
    if row and loveLevel >= 0 then
        ---@type RoleVoiceVo[]
        local t = {}
        local id_string = row:Get("ids")
        local ids = string.split(id_string, ',')
        local setting = settingMgr:GetSetting(voiceSettingPath, "RoleVoiceVo")
        for i, id in pairs(ids) do
            ---@type RoleVoiceVo
            local vo = setting:Get(id)
            if not string.isEmpty(vo.targetNum) then
                local tartNum = string.split(vo.targetNum, ',')
                local min, max = checkInt(tartNum[1]), checkInt(tartNum[2])
                if loveLevel >= min and loveLevel <= max then
                    local needCheck, isValid = self:IsValidTime(vo)
                    if needCheck then
                        ---需要检测时间的逻辑
                        if isValid then
                            table.insert(t, vo)
                        end
                    else
                        table.insert(t, vo)
                    end
                end
            end
        end
        if #t >0 then
            local position = math.random(1, #t)
            ---@type RoleVoiceVo
            local vo = t[position]
            CriWareUtils.PlayVoiceVoById(vo, go)
            return vo
        end
    end
end


