function RoleVoiceMgr:PlaySeriousInjuredVoiceByCardId(cardId)
    return self:__PlayVoiceByCardIdAndType(cardId, VoiceType.CARD_SERIOUS_INJURED)
end


---播放进入游戏的音频事件
---@param cardId number
---@return RoleVoiceVo | nil
function RoleVoiceMgr:PlayEnterGameVoiceByCardId(cardId)
    if checkNumber(cardId) == 0 then
        return nil
    end
    local t = self:PlayFestivalVoiceByCardId(cardId)
    if #t <= 0 then
        ---不存在特殊节日时，播放下面其他的逻辑
        ---是否存在新邮件
        if false then
            return self:PlayMailVoiceByCardId(cardId)
        else
            ---播进入的音频
            return self:__PlayRoleVoiceByCardIdAndLevel(cardId, VoiceType.HOME_ENTER)
        end
    end
end


---处理角色的语音播放的逻辑
---@param cardId number
---@param go UnityEngine.GameObject
---@return RoleVoiceVo | nil
function RoleVoiceMgr:__PlayRoleVoiceByCardId(cardId, type, go)
    ---@type CardVo
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    if cardVo then
        local roleId = cardVo.characterId
        local primaryKey = string.format('%s_%s', roleId, type)
        ---@type TableML.TableFile
        local tableFile = SettingModule.Get(voiceRolesSettingPath)
        ---@type TableML.TableFileRow
        local row = tableFile:GetByPrimaryKey(primaryKey, false)
        local settingMgr = SettingMgr:GetInstance()
        if row then
            local id_string = row:Get("ids")
            local ids = string.split(id_string, ',')
            local position = math.random(1, #ids)
            local id = ids[position]
            local setting = settingMgr:GetSetting(voiceSettingPath, "RoleVoiceVo")
            ---@type RoleVoiceVo
            local vo = setting:Get(id)
            CriWareUtils.PlayVoiceVoById(vo, go)
            return vo
        end
    end
end
